import java.io.File;
import java.io.IOException;
import java.nio.file.*;
import java.util.logging.Logger;
import java.util.stream.Stream;

public static boolean copyFolder(File source, File target, Logger log) {
    try {
        Files.walk(source.toPath())
                .forEach(sourcePath -> {
                    try {
                        Path destPath = target.toPath().resolve(sourcePath.relativize(source.toPath()));
                        Files.copy(sourcePath, destPath, StandardCopyOption.REPLACE_EXISTING);
                    } catch (IOException e) {
                        log.warning("Failed to copy: " + sourcePath + " to " + target + ": " + e.getMessage());
                    }
                });
        return true;
    } catch (IOException e) {
        log.warning("Failed to copy folder: " + e.getMessage());
        return false;
    }
}

